begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('e1100000-0000-0000-0000-000000000001','authenticated','authenticated','billing-a@example.test','',now(),'{}','{"name":"Billing A","company_name":"Billing QA A"}',now(),now()),
('e1100000-0000-0000-0000-000000000002','authenticated','authenticated','billing-b@example.test','',now(),'{}','{"name":"Billing B","company_name":"Billing QA B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('billing.company',private.current_company_id(),true);
insert into private.saas_billing_qa_tenants values(current_setting('billing.company'),'Synthetic Billing QA');
create function pg_temp.billing_action(a text,plan_code text default null,cycle text default 'monthly') returns jsonb language plpgsql security definer set search_path='' as $$
declare command jsonb;claims text:=current_setting('request.jwt.claims');result jsonb;payload jsonb;begin
 payload:=jsonb_build_object('revision',coalesce((select revision from public.saas_subscriptions where company_id=private.current_company_id()),0));
 if plan_code is not null then payload:=payload||(select jsonb_build_object('plan_id',id,'plan_revision',revision,'cycle',cycle) from public.saas_plans where code=plan_code);end if;
 command:=public.saas_billing_prepare(a,payload,gen_random_uuid());
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 result:=public.saas_billing_event(jsonb_build_object('command_id',command->>'command_id','event_id','mock-billing:'||(command->>'command_id'),'sequence',(command->>'revision')::integer,'state','confirmed_qa'));
 perform set_config('request.jwt.claims',claims,true);return result;
end $$;
grant execute on function pg_temp.billing_action(text,text,text) to authenticated;
select is(private.saas_period_end('2027-01-31 12:00Z','monthly',31),'2027-02-28 12:00Z'::timestamptz,'month clamp');
select is(private.saas_period_end('2027-02-28 12:00Z','monthly',31),'2027-03-31 12:00Z'::timestamptz,'month anchor restored');
select is(private.saas_period_end('2028-02-29 12:00Z','yearly',29),'2029-02-28 12:00Z'::timestamptz,'leap annual clamp');
select is(public.saas_billing_access()->>'managed','false','existing tenant unmanaged, no forced enrollment');
select ok(not has_function_privilege('authenticated','public.saas_billing_secret()','execute'),'secret inaccessible to browser');
select ok(not has_function_privilege('authenticated','public.saas_billing_event(jsonb)','execute'),'browser cannot confirm state');
select ok(not has_function_privilege('authenticated','public.saas_plan_admin(text,jsonb)','execute'),'tenant cannot edit central plans');
select ok(not has_table_privilege('authenticated','public.saas_subscriptions','insert'),'browser cannot forge subscription');
select ok(not has_table_privilege('authenticated','private.saas_billing_qa_tenants','insert'),'browser cannot allowlist tenant');
select ok(not private.saas_plan_valid('{"features":{},"limits":{"users":"unlimited"}}'),'string quota rejected safely');
set local role authenticated;
select throws_ok($$select public.saas_billing_prepare('start_trial','{"real_billing_enabled":true}',gen_random_uuid())$$,'22023','SAAS_REAL_BILLING_REQUIRES_EXPLICIT_AUTHORIZATION','real billing blocked');
select throws_ok($$select public.saas_billing_prepare('start_trial','{"price":0}',gen_random_uuid())$$,'22023','Billing: Preço, status e recursos são definidos no servidor.','price tampering blocked');
select throws_ok($$select public.saas_billing_prepare(null,'{}',gen_random_uuid())$$,'22023','Billing: Solicitação inválida.','null action denied');
select is(pg_temp.billing_action('start_trial','qa-essential')->>'result','applied','trial created through QA confirmation');
select is(public.saas_billing_access()->>'status','trial','trial status');
select is(public.saas_billing_source()#>>'{subscription,contract,monthly_price}','29.00','canonical price snapshot');
select is(public.saas_billing_source()#>>'{usage,users}','1','canonical active users');
select is((select count(*)::integer from public.saas_subscriptions),1,'one subscription');
select throws_ok($$select pg_temp.billing_action('start_trial','qa-essential')$$,'22023','Billing: Trial já utilizado por esta empresa.','trial cannot be restarted');
select lives_ok($$insert into public.products(id,company_id,name,pricing_type,sales_price) values('billing-p1',current_setting('billing.company'),'QA one','unidade',10),('billing-p2',current_setting('billing.company'),'QA two','unidade',10)$$,'products within quota');
select throws_ok($$insert into public.products(id,company_id,name,pricing_type,sales_price) values('billing-p3',current_setting('billing.company'),'QA three','unidade',10)$$,'42501','Billing: Limite de 2 produtos do plano atingido. Consulte Plano e Assinatura.','product quota enforced on direct REST equivalent');
select lives_ok($$update public.products set name='QA edited' where id='billing-p1'$$,'editing existing product at quota allowed');
select throws_ok($$select public.reports_source('dre',current_date,current_date,'{}',0,50)$$,'42501','Billing: Recurso indisponível no plano. Consulte Plano e Assinatura.','server read gate denies missing reports');
select throws_ok($$select public.saas_billing_assert('advanced_media')$$,'42501','Billing: Recurso indisponível no plano. Consulte Plano e Assinatura.','media API gate denies missing entitlement');
select lives_ok($$update public.products set name='Commercial edit',pricing_details='{"gallery_images":[],"video_url":""}' where id='billing-p1'$$,'empty media normalization does not require advanced media');
select throws_ok($$update public.products set pricing_details='{"video_url":"https://www.youtube.com/watch?v=abcdefghijk"}' where id='billing-p1'$$,'42501','Billing: Recurso indisponível no plano. Consulte Plano e Assinatura.','actual media change requires entitlement');
reset role;
update public.saas_subscriptions set started_at=started_at-interval '7 days' where company_id=current_setting('billing.company');
set local role authenticated;
select is(pg_temp.billing_action('activate')->>'result','applied','activation QA');
select is(public.saas_billing_access()->>'status','active','active status');
select throws_ok($$select pg_temp.billing_action('activate')$$,'22023','Billing: Transição indisponível para o estado atual.','cannot reset active period by activating again');
reset role;
select is((select billing_anchor from public.saas_subscriptions where company_id=current_setting('billing.company')),extract(day from clock_timestamp() at time zone 'UTC')::integer,'paid anchor set at activation');
select set_config('billing.start',(select current_period_start::text from public.saas_subscriptions where company_id=current_setting('billing.company')),true);
set local role authenticated;
select is(pg_temp.billing_action('change_plan','qa-complete','yearly')->>'result','applied','upgrade immediate');
select is(public.saas_billing_access()#>>'{features,reports}','true','upgrade enables entitlement');
select lives_ok($$insert into public.products(id,company_id,name,pricing_type,sales_price) values('billing-p3',current_setting('billing.company'),'QA three','unidade',10)$$,'upgrade increases quota');
select is(pg_temp.billing_action('change_plan','qa-essential')->>'result','applied','downgrade allowed');
select is(public.saas_billing_source()#>>'{usage,products}','3','downgrade preserves excess products');
select throws_ok($$insert into public.products(id,company_id,name,pricing_type,sales_price) values('billing-p4',current_setting('billing.company'),'QA four','unidade',10)$$,'42501','Billing: Limite de 2 produtos do plano atingido. Consulte Plano e Assinatura.','over quota blocks creation only');
select is(pg_temp.billing_action('payment_failed')->>'result','applied','failed payment simulated');
select is(public.saas_billing_access()->>'status','past_due','past due status');
select is(pg_temp.billing_action('grace')->>'result','applied','grace started');
select is(public.saas_billing_access()->>'read_only','false','grace preserves operation');
select is(pg_temp.billing_action('renew')->>'result','applied','renewal simulated');
select is(public.saas_billing_access()->>'status','active','renewal restores active');
select is(pg_temp.billing_action('cancel')->>'result','applied','cancellation scheduled');
select is(public.saas_billing_source()#>>'{subscription,cancel_at_period_end}','true','cancel at period end');
select is(public.saas_billing_access()->>'read_only','false','scheduled cancellation preserves access');
select is(pg_temp.billing_action('reactivate')->>'result','applied','scheduled cancellation reversed');
select is(public.saas_billing_source()#>>'{subscription,cancel_at_period_end}','false','cancel flag cleared');
select is(pg_temp.billing_action('cancel')->>'result','applied','cancel again');
select is(pg_temp.billing_action('expire')->>'result','applied','simulate end of cancelled period');
select is(public.saas_billing_access()->>'status','cancelled','cancelled state');
select is(public.saas_billing_access()->>'read_only','true','cancelled read only');
select throws_ok($$update public.products set name='blocked' where id='billing-p1'$$,'42501','Billing: Assinatura em modo somente leitura. Seus dados e exportações estão preservados.','direct mutation denied when readonly');
select lives_ok($$select public.reports_receivable_source(current_date,current_date)$$,'critical historic export remains accessible');
select lives_ok($$select public.saas_billing_source()$$,'portal accessible after cancellation');
select is(pg_temp.billing_action('reactivate')->>'result','applied','reactivate expired/cancelled');
select is(pg_temp.billing_action('expire')->>'result','applied','QA expire trial or active');
