reset role;
select is((select count(*)::integer from public.products where company_id=current_setting('billing.company')),3,'no data deleted by lifecycle');
select is((select count(*)::integer from public.financial_transactions where company_id=current_setting('billing.company')),0,'SaaS events never enter Finance ledger');
select ok((select count(*)>10 from public.audit_logs where company_id=current_setting('billing.company') and module='saas_billing'),'subscription actions audited');
select is((select count(*)::integer from public.saas_subscriptions where company_id=current_setting('billing.company')),1,'single subscription after all lifecycle actions');
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.saas_subscriptions),0,'cross tenant subscription RLS');
select is((select count(*)::integer from public.saas_subscription_events),0,'cross tenant events RLS');
select throws_ok($$select public.saas_billing_prepare('start_trial','{}',gen_random_uuid())$$,'42501','Billing: Simulações permitidas somente em tenant QA habilitado.','real tenant cannot enroll itself');
reset role;
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select pg_temp.billing_action('reactivate');
