select set_config('billing.payload',jsonb_build_object('revision',(select revision from public.saas_subscriptions where company_id=current_setting('billing.company')))::text,true);
set local role authenticated;
select set_config('billing.command',public.saas_billing_prepare('renew',current_setting('billing.payload')::jsonb,current_setting('billing.operation')::uuid)::text,true);
select is(public.saas_billing_prepare('renew',current_setting('billing.payload')::jsonb,current_setting('billing.operation')::uuid)::text,current_setting('billing.command'),'prepare retry idempotent');
select throws_ok($$select public.saas_billing_prepare('cancel',current_setting('billing.payload')::jsonb,current_setting('billing.operation')::uuid)$$,'22023','Billing: Chave de operação reutilizada.','operation identity cannot change');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('billing.event',jsonb_build_object('command_id',current_setting('billing.operation'),'event_id','mock-billing:'||current_setting('billing.operation'),'sequence',(current_setting('billing.command')::jsonb->>'revision')::integer,'state','confirmed_qa')::text,true);
select is(public.saas_billing_event(current_setting('billing.event')::jsonb)->>'result','applied','confirmed callback applied');
