select throws_ok($$select public.saas_billing_event(current_setting('billing.event')::jsonb||'{"state":"active"}')$$,'22023','Billing: Evento inválido.','provider event must be QA');
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('billing.operation',gen_random_uuid()::text,true);
select set_config('billing.command',public.saas_billing_prepare('renew',jsonb_build_object('revision',(select revision from public.saas_subscriptions where company_id=current_setting('billing.company'))),current_setting('billing.operation')::uuid)::text,true);
select pg_temp.billing_action('cancel');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.saas_billing_event(jsonb_build_object('command_id',current_setting('billing.operation'),'event_id','mock-billing:'||current_setting('billing.operation'),'sequence',(current_setting('billing.command')::jsonb->>'revision')::integer,'state','confirmed_qa'))->>'result','stale','old prepared event cannot overwrite new subscription');
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
