select pg_temp.billing_action('change_plan','qa-complete');
insert into public.role_permissions(company_id,path,roles) values(current_setting('billing.company'),'/financial','{}') on conflict(company_id,path) do update set roles='{}';
set local role authenticated;
select throws_ok($$select public.finance_source()$$,'42501',null,'feature present and permission absent still denied');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('billing.company'),'/settings','{}') on conflict(company_id,path) do update set roles='{}';
set local role authenticated;
select throws_ok($$select public.saas_billing_source()$$,'42501','Billing denied','explicit settings deny also denies admin billing');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
delete from public.role_permissions where company_id=current_setting('billing.company') and path in ('/settings','/financial');
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select pg_temp.billing_action('change_plan','qa-essential');
insert into public.profiles(id,company_id,name,email,role,active) values('billing-seat2',current_setting('billing.company'),'QA seat 2','seat2@example.test','vendas',true);
select throws_ok($$insert into public.profiles(id,company_id,name,email,role,active) values('billing-seat3',current_setting('billing.company'),'QA seat 3','seat3@example.test','vendas',true)$$,'42501','Billing: Limite de 2 usuários ativos do plano atingido. Consulte Plano e Assinatura.','active user quota server enforced');
reset role;
insert into public.cash_register_sessions(id,company_id,opened_by) values('billing-cash',current_setting('billing.company'),'QA');
select pg_temp.billing_action('expire');
set local role authenticated;
select throws_ok($$insert into public.cash_register_transactions(session_id,type,amount) values('billing-cash','suprimento',10)$$,'42501','Billing: Assinatura em modo somente leitura. Seus dados e exportações estão preservados.','cash child table direct write cannot bypass read only');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.product_media_register(current_setting('billing.company'),'e1100000-0000-0000-0000-000000000001','x/products/x','x','x',10)$$,'42501','Billing: Assinatura em modo somente leitura. Seus dados e exportações estão preservados.','private media inventory cannot bypass read only');
select throws_ok($$select public.catalog_checkout(current_setting('billing.company'),gen_random_uuid(),gen_random_uuid(),repeat('a',64),'{}','[]',null)$$,'42501','Billing: Assinatura em modo somente leitura. Seus dados e exportações estão preservados.','checkout cannot bypass read only');
select set_config('billing.plan',public.saas_plan_admin('save','{"code":"qa-test-admin","name":"QA Test","monthly_price":1,"annual_price":10,"trial_days":3,"features":{"catalog":false},"limits":{"users":1,"products":1}}')::text,true);
select ok(current_setting('billing.plan')::jsonb->>'id' is not null,'service creates demonstration catalog plan');
select set_config('billing.plan',public.saas_plan_admin('save',current_setting('billing.plan')::jsonb||'{"name":"QA Changed","monthly_price":2}')::text,true);
select is(current_setting('billing.plan')::jsonb->>'monthly_price','2.00','service edits canonical price');
select set_config('billing.plan',public.saas_plan_admin('order',current_setting('billing.plan')::jsonb||'{"sort_order":9}')::text,true);
select is(current_setting('billing.plan')::jsonb->>'sort_order','9','service orders plans');
select set_config('billing.plan',public.saas_plan_admin('deactivate',current_setting('billing.plan')::jsonb)::text,true);
select is(current_setting('billing.plan')::jsonb->>'active','false','service deactivates plan');
select is((select count(*)::integer from private.saas_plan_audit where plan_id=(current_setting('billing.plan')::jsonb->>'id')::uuid),4,'all global plan changes audited separately');
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select pg_temp.billing_action('reactivate');
update public.saas_subscriptions set status='trial',trial_ends_at=now()-interval '1 second',cancel_at_period_end=false where company_id=current_setting('billing.company');
select is(private.saas_state(current_setting('billing.company'))->>'read_only','true','trial expiration resolves by server time');
update public.saas_subscriptions set status='grace',grace_ends_at=now()-interval '1 second' where company_id=current_setting('billing.company');
select is(private.saas_state(current_setting('billing.company'))->>'read_only','true','grace expiration resolves by server time');
update public.saas_subscriptions set status='active',current_period_start=now()-interval '2 days',current_period_end=now()-interval '1 day',grace_ends_at=null where company_id=current_setting('billing.company');
select is(private.saas_state(current_setting('billing.company'))->>'status','grace','overdue active enters central grace');
update public.saas_subscriptions set cancel_at_period_end=true where company_id=current_setting('billing.company');
select is(private.saas_state(current_setting('billing.company'))->>'status','cancelled','scheduled cancel resolves by time');
select pg_temp.billing_action('reactivate');
update public.saas_subscriptions set status='past_due',billing_anchor=31,current_period_start='2027-01-31 12:00Z',current_period_end='2027-02-28 12:00Z',grace_ends_at=now()+interval '3 days' where company_id=current_setting('billing.company');
select pg_temp.billing_action('renew');
select is((select current_period_start from public.saas_subscriptions where company_id=current_setting('billing.company')),'2027-02-28 12:00Z'::timestamptz,'late renewal preserves previous due date');
select is((select current_period_end from public.saas_subscriptions where company_id=current_setting('billing.company')),'2027-03-31 12:00Z'::timestamptz,'late renewal preserves calendar, no extra month');
insert into public.orders(id,company_id,customer_name,number,status,total_amount,shipping_cost,paid_amount) values('billing-role-order',current_setting('billing.company'),'Synthetic QA','QA-BILLING-ROLE','aguardando_pagamento',100,0,0);
update public.cash_register_sessions set status='fechado' where company_id=current_setting('billing.company');
insert into public.role_permissions(company_id,path,roles) values(current_setting('billing.company'),'/financial','{}') on conflict(company_id,path) do update set roles='{}';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.profiles set role='vendas' where auth_user_id='e1100000-0000-0000-0000-000000000001';
select set_config('request.jwt.claims','{"sub":"e1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.operate_cash_register('open',100,'Billing QA seller',null)->>'status','UPDATED','authorized POS seller can open cash without financial permission');
select is(public.record_order_payment_and_production('billing-role-order',10,'pix','parcial',null,null,(select updated_at from public.orders where id='billing-role-order'))->>'status','UPDATED','authorized Orders receipt retains its own permission boundary');
select throws_ok($$select public.finance_source()$$,'42501',null,'same seller still cannot open Finance');
reset role;
select * from finish();
rollback;

